const items = $input.all();
const results = [];

function buildLink(baseOrExisting, uid, name, email, period, token) {
  const host = 'http://192.168.2.123:3000';
  let link = baseOrExisting || '';
  if (!link || link.includes('localhost:3000')) {
    link = host + '/bieu-mau-danh-gia-360.html?token=' + encodeURIComponent(token) + '&period=' + encodeURIComponent(period) + '&name=' + encodeURIComponent(name) + '&email=' + encodeURIComponent(email) + '&userId=' + encodeURIComponent(uid);
  } else {
    link = link.replace('http://localhost:3000', host);
    if (!link.includes('email=')) link += '&email=' + encodeURIComponent(email);
    if (!link.includes('userId=')) link += '&userId=' + encodeURIComponent(uid);
  }
  return link;
}

for (const item of items) {
  const json = item.json;
  const body = json.body || json;

  // 1. Array of recipients from Web payload
  if (Array.isArray(body.recipients) && body.recipients.length > 0) {
    for (const r of body.recipients) {
      const uid = r.userId || r.id || 'usr-emp';
      const name = r.name || r.fullName || 'Nhân sự';
      const email = r.email || r.userEmail || '';
      const period = r.period || body.period || '2026-Q4';
      const deadline = r.deadline || body.deadline || '28 hàng tháng';
      const token = Buffer.from(uid + ':' + period + ':' + Date.now()).toString('base64url');
      const magicLink = buildLink(r.magicLink, uid, name, email, period, token);
      results.push({
        json: {
          userId: uid,
          fullName: name,
          email: email,
          department: r.department || r.dept || 'Toàn công ty',
          period: period,
          deadline: deadline,
          hasSubmitted: r.completed === true || r.hasSubmitted === true ? true : false,
          token: token,
          magicLink: magicLink
        }
      });
    }
  }
  // 2. Single recipient from Web payload
  else if (body.recipient) {
    const r = body.recipient;
    const uid = r.userId || r.id || 'usr-emp';
    const name = r.name || r.fullName || 'Nhân sự';
    const email = r.email || r.userEmail || '';
    const period = r.period || body.period || '2026-Q4';
    const deadline = r.deadline || body.deadline || '28 hàng tháng';
    const token = Buffer.from(uid + ':' + period + ':' + Date.now()).toString('base64url');
    const magicLink = buildLink(r.magicLink, uid, name, email, period, token);
    results.push({
      json: {
        userId: uid,
        fullName: name,
        email: email,
        department: r.department || r.dept || 'Toàn công ty',
        period: period,
        deadline: deadline,
        hasSubmitted: r.completed === true || r.hasSubmitted === true ? true : false,
        token: token,
        magicLink: magicLink
      }
    });
  }
  // 3. Direct user row from PostgreSQL query
  else if (json.email && json.fullName) {
    const uid = json.userId || json.id || 'usr-emp';
    const name = json.fullName || 'Nhân sự';
    const email = json.email;
    const period = json.period || '2026-Q4';
    const deadline = json.deadline || '28 hàng tháng';
    const token = Buffer.from(uid + ':' + period + ':' + Date.now()).toString('base64url');
    const magicLink = buildLink(json.magicLink, uid, name, email, period, token);
    results.push({
      json: {
        userId: uid,
        fullName: name,
        email: email,
        department: json.department || 'Toàn công ty',
        period: period,
        deadline: deadline,
        hasSubmitted: json.hasSubmitted === true || json.completed === true ? true : false,
        token: token,
        magicLink: magicLink
      }
    });
  }
}

return results;

